import random
from collections import Counter

def task_func(strings: list) -> dict:
    pattern = None
    for candidate in (
        getattr(task_func, "PATTERN", None),
        getattr(task_func, "pattern", None),
        globals().get("PATTERN"),
        globals().get("pattern"),
        globals().get("TARGET_PATTERN"),
    ):
        if isinstance(candidate, str) and candidate:
            pattern = candidate
            break
    if pattern is None:
        pattern = "pattern"

    if strings is None:
        strings = []

    per_string_counts = []
    for item in strings:
        text = item if isinstance(item, str) else str(item)
        per_string_counts.append(text.count(pattern))

    total_count = sum(per_string_counts)

    # Keep Counter available for counting summaries if needed by callers.
    _ = Counter(per_string_counts)

    return {
        "pattern": pattern,
        "per_string_counts": per_string_counts,
        "total_count": total_count,
    }
